# the parser and scanner can be regenerated by other yacc and lex
# implementations: the yacc and lex in PATH (such as bison and flex), if any
command -v yacc >/dev/null && command -v lex >/dev/null || { echo skipped; exit 0; }
cp "$SRCDIR"/*.c "$SRCDIR"/*.h "$SRCDIR"/bc.y "$SRCDIR"/scan.l "$SRCDIR"/Makefile .
rm -f bc.tab.c bc.tab.h scan.c
make YACC=yacc LEX=lex CC="$CC" STDFLAGS= CFLAGS=-O1 >build.log 2>&1 || { cat build.log; exit 1; }
printf 'scale=20; 4*a(1)\nx = 2^100; x\n' | ./bc -l
